pub fn subject_match_set(db: &Db, s: Subject) -> (Vec<u8>, Vec<u64>) {
    match s {
        Subject::User(uid) => {
            let mut types = Vec::new();
            types.push(0);
            types.push(1);
            (types, expand_user(db, uid))
        }
        Subject::Group(g) => {
            let mut types = Vec::new();
            types.push(1);
            let mut ids = Vec::new();
            ids.push(g);
            (types, ids)
        }
        Subject::Token(t) => {
            let mut types = Vec::new();
            types.push(2);
            let mut ids = Vec::new();
            ids.push(t);
            (types, ids)
        }
    }
}

