/// D5 `forbid_external_sharing` gate, shared by every entry point
/// that creates a grant on a resource in this drive
/// (`grant_handler::create_grant`,
/// `DriveManagementService::set_member_role`). Each caller
/// resolves `is_external` from whichever source naturally fits
/// (the just-created `User` entity in the email path, a
/// `get_user_flags` probe in the user-by-id path); the gate
/// itself owns the decision + audit + canonical error so the
/// shape stays in lockstep across surfaces. See `docs/plan/drive.md` §8.
///
/// Returns `Ok(())` when the subject is allowed (policy off, subject
/// is not a User, or the User is not external). Returns
/// `OperationNotSupported` after emitting a `grant.rejected` audit
/// line otherwise.
pub fn refuse_external_sharing(
    &self,
    subject: Subject,
    is_external: bool,
    ctx: ExternalSharingGateContext,
) -> Result<(), DomainError> {
    if !self.forbid_external_sharing {
        return Ok(());
    }
    let Subject::User(uid) = subject else {
        return Ok(());
    };
    if !is_external {
        return Ok(());
    }
    tracing::info!(
        target: "audit",
        event = "grant.rejected",
        reason = "forbid_external_sharing",
        stage = ctx.stage,
        caller_id = %ctx.caller_id,
        subject_id = %uid,
        drive_id = ?ctx.drive_id,
        resource_type = ?ctx.resource_type,
        resource_id = ?ctx.resource_id,
        "👮🏻‍♂️ grant refused: forbid_external_sharing",
    );
    Err(DomainError::operation_not_supported(
        "Grant",
        "This drive does not allow external sharing.",
    ))
}

src/application/services/drive_managemen.code:
/// D5 `forbid_external_sharing` for `set_member_role`. Fetches the
/// data this surface has but grant_handler doesn't (drive policies +
/// user flags), then defers the decision + audit + canonical error
/// to `DrivePolicies::refuse_external_sharing` — the same gate
/// `grant_handler::create_grant` runs for File/Folder resources. One
/// rejection shape across both entry points.
///
/// Group / Token subjects can't be external by construction, so the
/// user lookup is skipped (the gate handles those branches too, but
/// returning early avoids a wasted SELECT on the drive row).
async fn refuse_if_forbid_external_sharing(
    &self,
    drive_id: Uuid,
    subject: Subject,
    caller_id: Uuid,
) -> Result<(), DomainError> {
    let Subject::User(uid) = subject else {
        return Ok(());
    };
    let drive = self.drive_repo.get_by_id(drive_id).await.map_err(|e| {
        DomainError::internal_error("Drive", format!("Failed to fetch drive: {e:?}"))
    })?;
    let policies = drive.drive.typed_policies();
    if !policies.forbid_external_sharing {
        return Ok(());
    }
    let flags = self
        .user_repo
        .get_user_flags(uid)
        .await
        .map_err(|e| DomainError::internal_error("User", format!("flags lookup: {e:?}")))?;
    policies.refuse_external_sharing(
        subject,
        flags.is_external,
        crate::domain::entities::drive::ExternalSharingGateContext {
            caller_id,
            stage: "drive_member",
            drive_id: Some(drive_id),
            resource_type: None,
            resource_id: None,
        },
    )
}

/// D5 `forbid_owner_role_change`. Fetches drive policies (one PK
/// probe), bails out early when the policy is off or the caller is
/// admin, then determines whether the requested op actually
/// mutates the Owner roster:
///
/// - `new_role = Some(Role::Owner)` — Owner add or refresh. Owner
///   roster mutation.
/// - `new_role = Some(Role::X)` and subject is currently Owner —
///   demotion. Owner roster mutation.
/// - `new_role = None` (remove) and subject is currently Owner —
///   removal. Owner roster mutation.
///
/// In any of those cases, defers to
/// `DrivePolicies::refuse_owner_role_change` for the audit + error.
async fn refuse_if_forbid_owner_role_change(
    &self,
    drive_id: Uuid,
    subject: Subject,
    new_role: Option<Role>,
    caller_id: Uuid,
    caller_is_admin: bool,
    operation: &'static str,
) -> Result<(), DomainError> {
    // Fast bypass for the tenant operator.
    if caller_is_admin {
        return Ok(());
    }
    let drive = self.drive_repo.get_by_id(drive_id).await.map_err(|e| {
        DomainError::internal_error("Drive", format!("Failed to fetch drive: {e:?}"))
    })?;
    let policies = drive.drive.typed_policies();
    if !policies.forbid_owner_role_change {
        return Ok(());
    }

    // Determine whether this op touches the Owner roster. An Owner
    // add (role == Owner) always does; a non-Owner write or a
    // removal only does when the subject currently holds Owner —
    // fetched lazily on the second case to skip the round-trip
    // when we already know the answer.
    let touches_owner = if matches!(new_role, Some(Role::Owner)) {
        true
    } else {
        let grants = self
            .authz
            .list_grants_on_resource(Resource::Drive(drive_id))
            .await?;
        grants
            .iter()
            .any(|g| g.subject == subject && matches!(g.role, Role::Owner))
    };
    if !touches_owner {
        return Ok(());
    }

    policies.refuse_owner_role_change(
        crate::domain::entities::drive::OwnerRoleChangeGateContext {
            caller_id,
            caller_is_admin,
            drive_id,
            operation,
            subject_type: subject.type_str(),
            subject_id: subject.id(),
        },
    )
}

/// Refuse the change if `subject` is currently the sole `Owner` on the
/// drive and the operation would remove or demote them. A shared drive
/// must always have at least one Owner — otherwise it becomes orphaned
/// (no one can ever grant permissions again).
async fn refuse_if_last_owner_change(
    &self,
    drive_id: Uuid,
    subject: Subject,
    caller_id: Uuid,
) -> Result<(), DomainError> {
    let resource = Resource::Drive(drive_id);
    let grants = self.authz.list_grants_on_resource(resource).await?;

    // `subject` must currently BE an owner — otherwise no demotion risk.
    let subject_is_owner = grants
        .iter()
        .any(|g| g.subject == subject && matches!(g.role, Role::Owner));
    if !subject_is_owner {
        return Ok(());
    }

    let owner_count = grants
        .iter()
        .filter(|g| matches!(g.role, Role::Owner))
        .count();
    if owner_count <= 1 {
        tracing::info!(
            target: "audit",
            event = "drive_membership.rejected",
            reason = "last_owner",
            drive_id = %drive_id,
            caller_id = %caller_id,
            subject_type = subject.type_str(),
            subject_id = %subject.id(),
            "👮🏻‍♂️ refused last-owner removal on drive {drive_id}",
        );
        return Err(DomainError::validation_error(
            "A shared drive must keep at least one Owner — promote another \
             member to Owner first, or delete the drive.",
        ));
    }
    Ok(())
}

/// Personal drives are single-user single-owner; any member mutation is
/// a category error (§2). Returns `Forbidden` with an audit line.
async fn refuse_if_personal(&self, drive_id: Uuid, op: &str) -> Result<(), DomainError> {
    let drive = self.drive_repo.get_by_id(drive_id).await.map_err(|e| {
        DomainError::internal_error("Drive", format!("Failed to fetch drive: {e:?}"))
    })?;
    if matches!(drive.drive.kind, DriveKind::Personal) {
        tracing::info!(
            target: "audit",
            event = "drive_membership.rejected",
            reason = "personal_drive_immutable",
            operation = %op,
            drive_id = %drive_id,
            "👮🏻‍♂️ refused {op} on personal drive {drive_id}",
        );
        return Err(DomainError::operation_not_supported(
            "Drive",
            "Personal drives have a fixed single-owner membership and cannot be modified.",
        ));
    }
    Ok(())
}

/// `DELETE /api/drives/{id}/members/{subject_id}`. Idempotent — removing
/// a subject with no current grant succeeds (matches `clear_role`).
///
/// `caller_is_admin` mirrors `set_member_role`: skips the per-drive
/// `Manage` check but keeps personal-drive guard + last-owner
/// protection. Audit emits `drive_membership.removed_via_admin`
/// when the bypass fires.
pub async fn remove_member(
    &self,
    caller_id: Uuid,
    caller_is_admin: bool,
    drive_id: Uuid,
    subject: Subject,
) -> Result<(), DomainError> {
    let resource = Resource::Drive(drive_id);
    if !caller_is_admin {
        self.authz
            .require(Subject::User(caller_id), Permission::Manage, resource)
            .await?;
    }

    self.refuse_if_personal(drive_id, "remove_member").await?;

    // D5: `forbid_owner_role_change` — locks the Owner roster
    // against non-admin callers. Fires when this would remove a
    // current Owner.
    self.refuse_if_forbid_owner_role_change(
        drive_id,
        subject,
        None, // None = removal, not a role write
        caller_id,
        caller_is_admin,
        "remove_member",
    )
    .await?;

    self.refuse_if_last_owner_change(drive_id, subject, caller_id)
        .await?;

    self.authz.clear_role(subject, resource).await?;

    // Mirror of `set_member_role`'s cache invalidation: after
    // clearing a role we MUST drop the `drive_role_cache` entries
    // targeting this drive, otherwise the just-removed subject's
    // former role stays visible until TTL expires. Same anti-drift
    // reason as the sibling add path above.
    self.authz
        .invalidate_drive_role_cache_for_drive(drive_id)
        .await;
    // And the repo's readable-drives cache: the drive must vanish
    // from the removed subject's list immediately.
    match subject {
        Subject::User(uid) => self.drive_repo.invalidate_readable_for_user(uid).await,
        _ => self.drive_repo.invalidate_readable_all(),
    }

    // D6 §11: canonical `drive.member_removed` audit event covers
    // every successful removal (owner-driven or admin bypass).
    // `via_admin` replaces the separate
    // `drive_membership.removed_via_admin` event — single name,
    // one boolean field for the bypass signal.
    tracing::info!(
        target: "audit",
        event = "drive.member_removed",
        drive_id = %drive_id,
        subject_type = subject.type_str(),
        subject_id = %subject.id(),
        via_admin = caller_is_admin,
        by = %caller_id,
        "👋 drive member removed",
    );
    Ok(())
}

src/application/ports/authorization_port.code:
/// Graduated-denial wrapper around `check`. Semantics:
///
/// - `permission` granted → `Ok(())`
/// - `permission` denied, `Read` also denied → `DomainError::not_found`
///   (404, anti-enumeration — same shape as "doesn't exist" so a probing
///   caller can't distinguish "wrong id" from "no access")
/// - `permission` denied, `Read` granted → `DomainError::access_denied`
///   (403 — the caller can already see the resource, so hiding existence
///   leaks nothing new; a clear 403 beats a confusing 404 for UX and for
///   API-first clients like rclone)
///
/// Special case: when `permission == Read`, the visibility gate collapses
/// onto itself — a `Read` denial IS a "hidden" outcome by definition, so
/// the method short-circuits to the strict anti-enum 404 without a second
/// DB round-trip. That's why there's only one method: strict Read-denial
/// and graduated write-denial fall out of the same signature.
///
/// Do NOT use this in search / enumeration paths where existence itself is
/// the attack vector — those must filter at the SQL/index layer, never
/// touch this method with per-row ids. Cross-tenant probes on ids the
/// caller has no prior read handle for degrade to the 404 shape naturally
/// (Read denied → `Hidden`).
///
/// [`Self::require_any`] is the multi-credential form and produces its
/// denial shape by delegating here, so the semantics above are the single
/// definition for both.
async fn require(
    &self,
    subject: Subject,
    permission: Permission,
    resource: Resource,
) -> Result<(), DomainError> {
    if self.check(subject, permission, resource).await? {
        // Granted path: high-traffic (every authorized request hits
        // this), so kept at `debug` and structured for grep-friendly
        // filtering. Not an audit event — the audit trail focuses
        // on denials and explicit mutations elsewhere.
        tracing::debug!(
            target: "oxicloud::authz",
            event = "authz.allowed",
            subject_type = subject.type_str(),
            subject_id = %subject.id(),
            permission = permission.as_str(),
            resource_type = resource.type_str(),
            resource_id = %resource.id(),
            "👮🏻‍♂️ perms: ✔ Subject '{}' has permission to '{}' on resource '{}'",
            subject,
            permission,
            resource
        );
        return Ok(());
    }

    // Visibility probe. Short-circuit: when the target permission IS
    // `Read` and the check above returned false, we already know Read is
    // denied — visibility is `Hidden` by definition, no second DB hop.
    // Otherwise probe Read; a DB-hop failure here degrades to `Hidden` so
    // the caller sees the strict anti-enum shape (safe default).
    let visibility = if permission == Permission::Read {
        AuthzDenialVisibility::Hidden
    } else if self
        .check(subject, Permission::Read, resource)
        .await
        .unwrap_or(false)
    {
        AuthzDenialVisibility::Visible
    } else {
        AuthzDenialVisibility::Hidden
    };

    let (kind, id) = match resource {
        Resource::Folder(id) => ("Folder", id),
        Resource::File(id) => ("File", id),
        Resource::Drive(id) => ("Drive", id),
        Resource::Calendar(id) => ("Calendar", id),
        Resource::AddressBook(id) => ("AddressBook", id),
        Resource::Playlist(id) => ("Playlist", id),
    };

    // Audit-worthy: denials are the interesting signal. Routed through
    // the `audit` tracing target so log aggregators can surface them
    // separately from operational debug traffic. Span context
    // (request_id, client_ip, user_id) comes from the request-scope
    // span set in `interfaces/middleware/trace_span.rs`, so this line
    // doesn't need to duplicate those fields.
    //
    // The `visibility` field discriminates the two denial shapes for
    // operators grepping exists-but-denied vs fully-hidden. `visible`
    // denials are the ones surfaced to the caller as 403 (and safe to
    // detail in the UI); `hidden` denials are the 404 anti-enum path.
    tracing::info!(
        target: "audit",
        event = "authz.denied",
        visibility = visibility.as_str(),
        subject_type = subject.type_str(),
        subject_id = %subject.id(),
        permission = permission.as_str(),
        resource_type = resource.type_str(),
        resource_id = %resource.id(),
        "👮🏻‍♂️ perms: ⛔ Subject '{}' hasn't permission to '{}' on resource '{}' (visibility={})",
        subject,
        permission,
        resource,
        visibility.as_str()
    );

    match visibility {
        AuthzDenialVisibility::Visible => Err(DomainError::access_denied(
            kind,
            format!("Missing '{}' permission on {} {}", permission, kind, id),
        )),
        AuthzDenialVisibility::Hidden => Err(DomainError::not_found(kind, id.to_string())),
    }
}

