src/application/services/drive_managemen.code:
/// `POST /api/drives/{id}/members` (create) or
/// `PATCH /api/drives/{id}/members/{subject_id}` (role change).
///
/// `set_role` is idempotent — `(subject, resource)` is unique — so the
/// two HTTP shapes share one service method. Returns the resulting grant.
///
/// `caller_is_admin = true` skips the per-drive `Manage` check
/// (used by `/api/admin/drives/{id}/members` so an admin who
/// created the drive for someone else can still edit owners).
/// Personal-drive guard and last-owner protection still apply —
/// admin bypass is about *access*, not invariants. The audit log
/// flags admin-driven changes via `via_admin = true` so a reader
/// can tell what fired the mutation. The caller (HTTP handler) is
/// authoritative for `caller_is_admin`; the route gate is the
/// source of truth and the service trusts the flag.
pub async fn set_member_role(
    &self,
    caller_id: Uuid,
    caller_is_admin: bool,
    drive_id: Uuid,
    subject: Subject,
    role: Role,
    expires_at: Option<chrono::DateTime<chrono::Utc>>,
) -> Result<Grant, DomainError> {
    let resource = Resource::Drive(drive_id);
    if !caller_is_admin {
        self.authz
            .require(Subject::User(caller_id), Permission::Manage, resource)
            .await?;
    }

    self.refuse_if_personal(drive_id, "set_member_role").await?;

    // D5: `forbid_external_sharing` on a shared drive — refuses
    // grant writes whose User subject is `is_external = true`.
    // Closes the `POST /api/drives/{id}/members` gap that
    // grant_handler's same-shaped check (covering `POST /api/grants`
    // only) doesn't reach. Group/Token subjects can't be external
    // by construction, so the lookup runs only for User subjects.
    // See `docs/plan/drive.md` §8.
    self.refuse_if_forbid_external_sharing(drive_id, subject, caller_id)
        .await?;

    // D5: `forbid_owner_role_change` — locks the Owner roster
    // against non-admin callers. Fires when this write would add a
    // new Owner (role == Owner) OR demote a current Owner
    // (subject is currently Owner and role != Owner).
    self.refuse_if_forbid_owner_role_change(
        drive_id,
        subject,
        Some(role),
        caller_id,
        caller_is_admin,
        "set_member_role",
    )
    .await?;

    // Demotion of the last owner = last-owner protection trips. A fresh
    // owner-role write or any non-owner subject is fine; only the case
    // "this subject is currently the only owner AND the new role is not
    // owner" is refused. Applies to admin-bypass too: orphaning a
    // shared drive is the same category error regardless of who fires
    // the request.
    if !matches!(role, Role::Owner) {
        self.refuse_if_last_owner_change(drive_id, subject, caller_id)
            .await?;
    }

    let grant = self
        .authz
        .set_role(caller_id, subject, role, resource, expires_at)
        .await?;

    // Drop the entire drive-role cache for this drive so the new
    // grant is visible on the very next `check` — without this, a
    // caller that gets Owner via `POST /api/drives/{id}/members`
    // then immediately acts on drive content (WebDAV cross-drive
    // MOVE, admin-driven cleanup, drive management) hits the
    // stale "no role for this subject on this drive" entry
    // seeded at some earlier `check`. TTL rescues eventually,
    // but the storage_cleanup_check.sh drain pattern hits this
    // race within a single test-second and fails on `authz.denied`
    // for admin's cascade to files inside.
    self.authz
        .invalidate_drive_role_cache_for_drive(drive_id)
        .await;
    // Same freshness contract for the repo's readable-drives cache:
    // the subject's drive list changed with this grant.
    match subject {
        Subject::User(uid) => self.drive_repo.invalidate_readable_for_user(uid).await,
        _ => self.drive_repo.invalidate_readable_all(),
    }

    // D6 §11: canonical `drive.member_added` audit event covers
    // every successful membership write (add + role-refresh, since
    // the underlying `set_role` is UPSERT — distinguishing the two
    // would require an additional read and bring no extra ops
    // value). `via_admin` carries the bypass signal that used to
    // live in a separate `drive_membership.set_via_admin` event;
    // log aggregators now have one canonical name per operation.
    tracing::info!(
        target: "audit",
        event = "drive.member_added",
        drive_id = %drive_id,
        subject_type = subject.type_str(),
        subject_id = %subject.id(),
        role = role.as_str(),
        via_admin = caller_is_admin,
        by = %caller_id,
        expires_at = ?expires_at,
        "🤝 drive member added",
    );
    Ok(grant)
}

src/domain/entities/drive.rs:368-407.code:
/// Effective policy = the kind's default, with the drive's explicit
/// overrides laid on top.
///
/// This is what every enforcement site consumes; none of them changed
/// when defaults landed, because they still receive a fully-resolved
/// `DrivePolicies`. Mirrors the SQL side exactly — `storage.drives_effective`
/// computes `default || overrides`, and `||` is right-biased in Postgres
/// for the same reason the overrides win here.
pub fn resolve(default: &DrivePolicies, overrides: &DrivePolicyOverrides) -> Self {
    Self {
        forbid_sharing: overrides.forbid_sharing.unwrap_or(default.forbid_sharing),
        forbid_external_sharing: overrides
            .forbid_external_sharing
            .unwrap_or(default.forbid_external_sharing),
        forbid_public_links: overrides
            .forbid_public_links
            .unwrap_or(default.forbid_public_links),
        forbid_cross_drive_move: overrides
            .forbid_cross_drive_move
            .unwrap_or(default.forbid_cross_drive_move),
        forbid_owner_role_change: overrides
            .forbid_owner_role_change
            .unwrap_or(default.forbid_owner_role_change),
        include_in_photo_index: overrides
            .include_in_photo_index
            .unwrap_or(default.include_in_photo_index),
        include_in_music_index: overrides
            .include_in_music_index
            .unwrap_or(default.include_in_music_index),
        read_only: overrides.read_only.unwrap_or(default.read_only),
        // `None` here genuinely means "inherit", so `.or()` rather than
        // `.unwrap_or()`: the default's own `None` (no cap) must survive.
        max_public_link_days: overrides
            .max_public_link_days
            .or(default.max_public_link_days),
        require_public_link_password: overrides
            .require_public_link_password
            .unwrap_or(default.require_public_link_password),
    }
}

src/domain/entities/drive.rs:480-530.code:
/// D5 `forbid_public_links` gate, used by every entry point that
/// mints an anonymous token-share on a resource in this drive
/// (`share_service::create_shared_link` today; future protocol
/// surfaces — e.g. NextCloud OCS share — must call this too). The
/// gate owns the decision + audit + canonical error so the
/// rejection shape stays in lockstep across surfaces. See
/// `docs/plan/drive.md` §8.
///
/// Returns `Ok(())` when the policy is off; emits a
/// `share.rejected` audit line and returns
/// `OperationNotSupported` when on.
pub fn refuse_public_links(&self, ctx: PublicLinkGateContext) -> Result<(), DomainError> {
    // `forbid_sharing` is the BROADER rule and covers public links too.
    // Three separate places already said so — the knob's own help text
    // ("covers public links and external sharing as well"), the
    // compliance scan, which reports existing links as violations under
    // it, and the admin editor, which greys `forbid_public_links` out as
    // "already enforced by Forbid per-resource sharing". Checking only
    // the narrow knob here made all three of those claims false: a link
    // could still be minted on a drive that forbade sharing outright,
    // while the UI told the admin it could not.
    //
    // Report the NARROWER knob when both are on, since that is the one an
    // admin would relax to permit this link — same precedence the scan
    // uses, so a refusal and the finding for an existing link name the
    // same cause.
    let (reason, message) = if self.forbid_public_links {
        (
            "forbid_public_links",
            "This drive does not allow public links.",
        )
    } else if self.forbid_sharing {
        (
            "forbid_sharing",
            "This drive does not allow sharing individual files or folders, \
             which includes public links.",
        )
    } else {
        return Ok(());
    };
    tracing::info!(
        target: "audit",
        event = "share.rejected",
        reason = reason,
        caller_id = %ctx.caller_id,
        item_type = ctx.item_type,
        item_id = %ctx.item_id,
        "👮🏻‍♂️ public-link creation refused",
    );
    Err(DomainError::operation_not_supported("Share", message))
}

